manifestBefore:
{
  "manifest_version": 3,
  "name": "Managed lifecycle proof",
  "version": "1.0.0",
  "commands": {
    "wxt:reload-extension": {
      "description": "Reload the extension during development",
      "suggested_key": {
        "default": "Alt+R"
      }
    }
  },
  "background": {
    "type": "module",
    "service_worker": "background.js"
  },
  "action": {
    "default_title": "Managed reload proof",
    "default_popup": "popup.html"
  },
  "host_permissions": [
    "http://localhost/*"
  ],
  "content_security_policy": {
    "extension_pages": "script-src 'self' 'wasm-unsafe-eval' http://localhost:51361; object-src 'self';",
    "sandbox": "script-src 'self' 'unsafe-inline' 'unsafe-eval' http://localhost:51361; sandbox allow-scripts allow-forms allow-popups allow-modals; child-src 'self';"
  },
  "permissions": [
    "tabs",
    "scripting"
  ]
}

